"""A2A server helpers shared by the Sanic integration."""

from __future__ import annotations

import json
from functools import lru_cache
from pathlib import Path
from typing import TYPE_CHECKING, Optional

from a2a.types import AgentCapabilities, AgentCard
from pydantic import ValidationError

from rasa.core.a2a_server.agent_card_generator import AgentCardGenerator
from rasa.core.a2a_server.config import A2AServerConfig
from rasa.shared.exceptions import RasaException

if TYPE_CHECKING:
    from rasa.core.agent import Agent
    from rasa.shared.core.flows import FlowsList


def resolve_agent_card(
    config: A2AServerConfig,
    *,
    flows: Optional["FlowsList"] = None,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
    assistant_name: str | None = None,
    version: str = "1.0.0",
) -> AgentCard:
    """Load or build the ``AgentCard`` advertised by the A2A server.

    When ``agent_card_path`` is set, the static JSON file is loaded and its
    ``url`` is overwritten with ``config.effective_url(...)``.  Repeated calls
    with the same arguments hit a bounded cache so the file is not re-read on
    every request.

    When ``agent_card_path`` is absent and ``flows`` is provided, an
    ``AgentCardGenerator`` builds the card from user-facing flows. This path is
    never cached because flow metadata (descriptions, default-flow flags) can
    differ between ``FlowsList`` instances that share the same flow IDs.

    Otherwise a minimal placeholder card is returned (used before the agent
    model is loaded at startup). Placeholders are cheap to construct and are not
    cached to avoid accumulating entries for every distinct
    ``(port, interface, scheme)`` combination seen during the process lifetime.
    """
    if config.agent_card_path:
        return _load_static_agent_card_cached(
            config.agent_card_path,
            config.url,
            config.description,
            config.include_conversation_repair,
            port,
            interface,
            scheme,
        )

    if flows is not None:
        return AgentCardGenerator.generate(
            config,
            flows,
            port=port,
            interface=interface,
            scheme=scheme,
            assistant_name=assistant_name,
            version=version,
        )

    return _placeholder_agent_card(
        config,
        port=port,
        interface=interface,
        scheme=scheme,
    )


@lru_cache(maxsize=32)
def _load_static_agent_card_cached(
    agent_card_path: str,
    url: str | None,
    description: str,
    include_conversation_repair: bool,
    port: int | None,
    interface: str | None,
    scheme: str | None,
) -> AgentCard:
    """Read and validate a static AgentCard JSON file.

    Bounded to 32 entries: a typical deployment has a single file path with a
    fixed (port, interface, scheme), so the cache stays at one or two entries
    in production.  Tests call ``clear_agent_card_cache()`` between cases.
    """
    config = A2AServerConfig(
        url=url,
        agent_card_path=agent_card_path,
        description=description,
        include_conversation_repair=include_conversation_repair,
    )
    return _load_static_agent_card(
        config,
        port=port,
        interface=interface,
        scheme=scheme,
    )


async def resolve_a2a_agent_card_at_startup(
    agent: "Agent",
    config: A2AServerConfig,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    """Resolve the runtime AgentCard once the agent model (and flows) are loaded."""
    if config.agent_card_path:
        return _load_static_agent_card(
            config,
            port=port,
            interface=interface,
            scheme=scheme,
        )

    if agent.processor is None:
        raise RasaException(
            "Cannot generate A2A agent card: agent model is not loaded."
        )

    flows = await agent.processor.get_flows()
    assistant_name = _assistant_display_name(agent)
    return resolve_agent_card(
        config,
        flows=flows,
        port=port,
        interface=interface,
        scheme=scheme,
        assistant_name=assistant_name,
        version=_agent_card_version(agent),
    )


def _agent_card_version(agent: "Agent") -> str:
    """Derive the AgentCard ``version`` from the loaded model."""
    model_name = agent.model_name
    if model_name:
        if model_name.endswith(".tar.gz"):
            return model_name[: -len(".tar.gz")]
        return model_name

    if model_id := agent.model_id:
        return model_id

    return "1.0.0"


def _assistant_display_name(agent: "Agent") -> str:
    domain_config = getattr(agent.domain, "config", None) or {}
    assistant_id = domain_config.get("assistant_id")
    if assistant_id:
        return str(assistant_id)
    return "Rasa Agent"


def _placeholder_agent_card(
    config: A2AServerConfig,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    return AgentCard(
        name="Rasa Agent",
        description=config.description,
        url=config.effective_url(port=port, interface=interface, scheme=scheme),
        version="1.0.0",
        default_input_modes=["text", "text/plain"],
        default_output_modes=["text", "text/plain"],
        capabilities=AgentCapabilities(
            streaming=True,
            push_notifications=config.push_notifications_enabled,
        ),
        skills=[],
    )


def _load_static_agent_card(
    config: A2AServerConfig,
    *,
    port: int | None = None,
    interface: str | None = None,
    scheme: str | None = None,
) -> AgentCard:
    path = Path(config.agent_card_path)
    try:
        card_data = json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise RasaException(f"A2A agent card file not found: '{path}'") from exc
    except OSError as exc:
        raise RasaException(
            f"Could not read A2A agent card file '{path}': {exc}"
        ) from exc
    except json.JSONDecodeError as exc:
        raise RasaException(
            f"A2A agent card file '{path}' contains invalid JSON: {exc}"
        ) from exc

    card_data["url"] = config.effective_url(
        port=port, interface=interface, scheme=scheme
    )
    try:
        return AgentCard.model_validate(card_data)
    except ValidationError as exc:
        raise RasaException(
            f"A2A agent card file '{path}' does not match the AgentCard "
            f"schema: {exc}"
        ) from exc
